// Task store module — no top-level side effects, no module-level I/O.
// All persistence is injected via a storage object: { load(): array, save(array): void }.

import fs from "node:fs";

/**
 * Creates a task store backed by the given storage.
 * @param {{ load(): Array, save(Array): void }} storage
 */
export function createTaskStore(storage) {
  let tasks = storage.load();

  const persist = () => storage.save(tasks);

  return {
    addTask(title) {
      // Monotonic ids: derive the next id from the highest id ever stored,
      // so completing/removing tasks can never cause id reuse.
      const nextId = tasks.reduce((max, t) => Math.max(max, t.id), 0) + 1;
      const t = { id: nextId, title, done: false };
      tasks.push(t);
      persist();
      return t;
    },

    completeTask(id) {
      const t = tasks.find((x) => x.id === id);
      if (!t) throw new Error(`no such task: ${id}`);
      t.done = true;
      persist();
      return t;
    },

    listOpen() {
      return tasks.filter((t) => !t.done);
    },
  };
}

/** File-backed storage. Reads lazily; only touches disk on load/save calls. */
export function fileStorage(path) {
  return {
    load() {
      try {
        return JSON.parse(fs.readFileSync(path, "utf8"));
      } catch (err) {
        if (err.code === "ENOENT") return [];
        throw err;
      }
    },
    save(tasks) {
      fs.writeFileSync(path, JSON.stringify(tasks));
    },
  };
}

/** In-memory storage. Nothing ever touches disk. */
export function memoryStorage() {
  let data = [];
  return {
    load() {
      return data;
    },
    save(tasks) {
      data = tasks;
    },
  };
}

