import { test, describe, it, before } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { mkdtemp, rm, readdir } from "node:fs/promises";
import { existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createTaskStore, fileStorage, memoryStorage } from "./tasks.mjs";

const MODULE_PATH = join(dirname(fileURLToPath(import.meta.url)), "tasks.mjs");

describe("createTaskStore with memoryStorage", () => {
  it("add/complete/listOpen flow", () => {
    const store = createTaskStore(memoryStorage());
    const a = store.addTask("alpha");
    const b = store.addTask("beta");
    assert.deepEqual(store.listOpen(), [a, b]);

    store.completeTask(a.id);
    assert.equal(a.done, true);
    assert.deepEqual(store.listOpen(), [b]);
  });

  it("throws on unknown id", () => {
    const store = createTaskStore(memoryStorage());
    assert.throws(() => store.completeTask(999), /no such task/);
  });

  it("ids stay unique and monotonic: adding 2, completing 1, adding 1 more yields ids 1,2,3", () => {
    const store = createTaskStore(memoryStorage());
    const t1 = store.addTask("one");
    const t2 = store.addTask("two");
    store.completeTask(t1.id); // id 1 is now done
    const t3 = store.addTask("three");

    // Original scheme used tasks.length + 1 and would have reused id 2 here.
    assert.equal(t1.id, 1);
    assert.equal(t2.id, 2);
    assert.equal(t3.id, 3);

    const ids = [t1.id, t2.id, t3.id];
    assert.equal(new Set(ids).size, 3, "ids must be unique");
  });
});

describe("createTaskStore with fileStorage", () => {
  let dir;

  before(async () => {
    dir = await mkdtemp(join(tmpdir(), "tasks-test-"));
  });

  it("state survives across two createTaskStore calls", async () => {
    const dbFile = join(dir, "db.json");
    const store1 = createTaskStore(fileStorage(dbFile));
    const t1 = store1.addTask("persistent");
    store1.completeTask(t1.id);
    const t2 = store1.addTask("also persistent");

    // Fresh store instance over the same file sees the persisted state.
    const store2 = createTaskStore(fileStorage(dbFile));
    assert.deepEqual(
      store2.listOpen().map((t) => t.title),
      ["also persistent"],
    );
    // And the monotonic id survives reload too.
    const t3 = store2.addTask("third");
    assert.equal(t3.id, 3);
  });

  it("does not touch the file until a write happens", async () => {
    const dbFile = join(dir, "lazy.json");
    createTaskStore(fileStorage(dbFile)); // construct only
    assert.equal(existsSync(dbFile), false);
  });
});

describe("module purity", () => {
  it("importing the module performs no filesystem writes", async () => {
    const sandbox = await mkdtemp(join(tmpdir(), "import-purity-"));
    try {
      const before = (await readdir(sandbox)).sort();
      // Import the module in a child process with cwd set to an empty temp dir.
      execFileSync(
        process.execPath,
        ["--input-type=module", "-e", `await import(${JSON.stringify(MODULE_PATH)});`],
        { cwd: sandbox },
      );
      const after = (await readdir(sandbox)).sort();
      assert.deepEqual(after, before, "importing must not create files in cwd");

      // Also ensure the legacy hardcoded DB location was never created.
      assert.equal(existsSync("/workspace/tasks.json"), false);
    } finally {
      await rm(sandbox, { recursive: true, force: true });
    }
  });
});

